-- Gerado por scripts/insert_natal_deco.mjs — "Anjo com Estrias" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('anjo', 'Anjo com Estrias', 'Anjo de Natal com saia às estrias, cabeça redonda, asas e auréola. Imprime de pé, sem suportes.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['anjo', 'natal', 'decoração', 'estrias'], 1, $tpl$// Anjo com Estrias — o modelo está em templates/decoracao/partes/anjo.scad (backend)
include </app/templates/decoracao/anjo.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"anjo","ui":{"widget":"hidden"}},"altura":{"order":1,"type":"number","min":60,"max":200,"unit":"mm","default":110,"ui":{"label":"Altura","widget":"slider","step":1}},"largura":{"order":2,"type":"number","min":30,"max":120,"unit":"mm","default":60,"ui":{"label":"Largura da saia","widget":"slider","step":1}},"estrias":{"order":3,"type":"number","min":8,"max":60,"default":24,"ui":{"label":"Número de estrias","widget":"slider","step":1}},"relevo":{"order":4,"type":"number","min":0,"max":4,"unit":"mm","default":1.5,"ui":{"label":"Fundura das estrias","widget":"slider","step":0.1}},"asas":{"order":5,"type":"number","min":50,"max":160,"unit":"%","default":100,"ui":{"label":"Tamanho das asas","widget":"slider","step":5}},"aureola":{"order":6,"type":"boolean","default":true,"ui":{"label":"Auréola","widget":"checkbox"}},"info_anjo":{"order":99,"default":null,"ui":{"widget":"info","text":"👼 Imprime de pé, sem suportes. Fica bonito em branco ou bege, com a auréola a dourado (troca de cor na camada onde a cabeça acaba)."}}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
